447	  if (!Object.hasOwn(node, 'result') || node.result === undefined) return;
448	  let cloned;
449	  try {
450	    cloned = structuredClone(node.result);
451	  } catch {
452	    throw new Error(`end node ${node.id}: result must be a structured-cloneable value (objects and arrays must not contain functions)`);
453	  }
454	  if (containsSharedMemory(cloned)) {
455	    throw new Error(`end node ${node.id}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`);
456	  }
457	}
