459	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
460	// name a single successor or a non-empty, duplicate-free array of successors;
461	// conditions keep their then/else pair and end nodes have none.
462	function normalizeSuccessors(node, nodes) {
463	  if (node.type === 'end') return [];
464	  if (node.type === 'condition') {
465	    for (const destination of [node.then, node.else]) {
466	      if (typeof destination !== 'string' || !nodes.has(destination)) {
467	        throw new Error(`node ${node.id} points to an unknown destination`);
468	      }
469	    }
470	    return [node.then, node.else];
471	  }
472	  const next = node.next;
473	  if (Array.isArray(next)) {
474	    if (next.length === 0) {
475	      throw new Error(`node ${node.id}: next array must not be empty`);
476	    }
477	    const seen = new Set();
478	    for (const destination of next) {
479	      if (typeof destination !== 'string') {
480	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
481	      }
482	      if (seen.has(destination)) {
483	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
484	      }
485	      seen.add(destination);
486	      if (!nodes.has(destination)) {
487	        throw new Error(`node ${node.id} points to an unknown destination`);
488	      }
489	    }
490	    return [...seen];
491	  }
492	  if (typeof next !== 'string' || !nodes.has(next)) {
493	    throw new Error(`node ${node.id} points to an unknown destination`);
494	  }
495	  return [next];
496	}
