498	// Resolves the explicit dependencies of a node. Dependencies only gate when a
499	// node may run; they never activate it. A missing dependsOn means no
500	// dependencies, and the entry node must not declare any.
501	function normalizeDependencies(node, nodes, entryId) {
502	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
503	  if (!Array.isArray(node.dependsOn)) {
